import type { JSX } from "preact";
import { useEffect, useRef, useState } from "preact/hooks";
import {
  buildAuthorizeUrl,
  fetchInstance,
  makeChallenge,
  makeState,
  makeVerifier,
  normalizeInstanceInput,
  openAuthorize,
  PENDING_AUTH_KEY,
  registerApp,
  supportsPKCE,
  type InstanceSummary,
  type PendingAuth,
} from "../api/auth";
import loginCat from "../assets/login-cat.png";
import supportQr from "../assets/support-qr.png";
import { t } from "../i18n/pt-BR";
import { sessionRead, sessionWrite } from "../lib/storage";
import { store } from "../state/store";
import { switchAccount } from "../state/boot";
import { Icon } from "../components/ui/Icon";
import "./login.css";

const APPS_KEY = "apps";

interface CachedApp {
  clientId: string;
  clientSecret?: string;
}

function readCachedApp(instance: string): CachedApp | null {
  const apps = sessionRead<Record<string, CachedApp>>(APPS_KEY, {});
  return apps[instance] ?? null;
}

function cacheApp(instance: string, app: CachedApp): void {
  const apps = sessionRead<Record<string, CachedApp>>(APPS_KEY, {});
  apps[instance] = app;
  sessionWrite(APPS_KEY, apps);
}

export function LoginPage(): JSX.Element {
  const [input, setInput] = useState("");
  const [busy, setBusy] = useState(false);
  const [instance, setInstance] = useState<InstanceSummary | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [supportOpen, setSupportOpen] = useState(false);
  const supportRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!supportOpen) return;
    const onDown = (e: PointerEvent): void => {
      if (!supportRef.current?.contains(e.target as Node)) setSupportOpen(false);
    };
    const onKey = (e: KeyboardEvent): void => {
      if (e.key === "Escape") setSupportOpen(false);
    };
    window.addEventListener("pointerdown", onDown);
    window.addEventListener("keydown", onKey);
    return () => {
      window.removeEventListener("pointerdown", onDown);
      window.removeEventListener("keydown", onKey);
    };
  }, [supportOpen]);

  const discover = async (e: Event): Promise<void> => {
    e.preventDefault();
    setError(null);
    const parsed = normalizeInstanceInput(input);
    if (!parsed) {
      setError(t.loginNotFound);
      return;
    }
    setBusy(true);
    try {
      const info = await fetchInstance(parsed.host);
      setInstance(info);
    } catch {
      setError(String(input).includes("@") ? t.loginNotFound : t.loginInstanceDown);
      setInstance(null);
    } finally {
      setBusy(false);
    }
  };

  const startLogin = async (): Promise<void> => {
    if (!instance) return;
    setBusy(true);
    setError(null);
    try {
      const host = instance.uri;
      let app = readCachedApp(host);
      if (!app) {
        app = await registerApp(host);
        cacheApp(host, app);
      }
      const pkce = await supportsPKCE(host);
      const pending: PendingAuth = {
        instance: host,
        clientId: app.clientId,
        clientSecret: app.clientSecret,
        pkce,
        state: makeState(),
        redirectAfter: "/",
      };
      if (pkce) {
        const verifier = makeVerifier();
        pending.codeVerifier = verifier;
        const challenge = await makeChallenge(verifier);
        sessionWrite(PENDING_AUTH_KEY, pending);
        openAuthorize(
          buildAuthorizeUrl({
            instance: host,
            clientId: app.clientId,
            pkce: true,
            codeChallenge: challenge,
            state: pending.state,
            forceLogin: store.accounts.length > 0,
          }),
        );
      } else {
        sessionWrite(PENDING_AUTH_KEY, pending);
        openAuthorize(
          buildAuthorizeUrl({
            instance: host,
            clientId: app.clientId,
            state: pending.state,
            forceLogin: store.accounts.length > 0,
          }),
        );
      }
    } catch (err) {
      console.warn("[oltn] login start failed", err);
      setError(t.errorAuth);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div class="login-page">
      <main class="login-main">
        <div class="login-stack">
          <div class="login-brand">
            <svg class="login-mark" viewBox="0 0 64 64" width={104} height={104} aria-hidden>
              <circle class="mark-ring" cx="32" cy="32" r="21" fill="none" strokeWidth="5" />
              <g class="mark-orbit">
                <circle cx="32" cy="11" r="6.5" />
              </g>
            </svg>
            <h1 class="login-wordmark">OLTN</h1>
            <p class="login-tagline">{t.tagline}</p>
            <p class="login-protocols" aria-label="Mastodon, Friendica, snac">
              <span>Mastodon</span>
              <span>Friendica</span>
              <span>snac</span>
            </p>
          </div>

          <div class="login-stage">
            <div class="login-card glass">
              {!instance ? (
                <form onSubmit={(e) => void discover(e)}>
                  <p class="login-lead">{t.loginSubtitle}</p>
                  <label class="login-label" htmlFor="instance">
                    {t.instanceLabel}
                  </label>
                  <input
                    id="instance"
                    class="field"
                    placeholder={t.instancePlaceholder}
                    value={input}
                    autocomplete="url"
                    autocapitalize="off"
                    spellcheck={false}
                    onInput={(e) => setInput((e.target as HTMLInputElement).value)}
                    autoFocus
                  />
                  <p class="login-hint">{t.instanceHint}</p>
                  {error && <p class="login-error">{error}</p>}
                  <button type="submit" class="btn primary block" disabled={busy || !input.trim()}>
                    {busy ? <span class="spinner" /> : <Icon name="arrow-right-line" size={16} />}
                    {busy ? t.loginLooking : t.loginButton}
                  </button>
                  <p class="login-note">
                    {t.loginMastodonIntro}{" "}
                    <a href="https://joinmastodon.org" target="_blank" rel="noopener noreferrer">
                      joinmastodon.org
                    </a>
                  </p>
                </form>
              ) : (
                <div class="instance-preview">
                  {instance.thumbnail && (
                    <img class="instance-thumb" src={instance.thumbnail} alt="" />
                  )}
                  <div class="instance-title">{instance.title}</div>
                  <div class="instance-uri muted">{instance.uri}</div>
                  {error && <p class="login-error">{error}</p>}
                  <div class="login-actions">
                    <button
                      type="button"
                      class="btn ghost"
                      onClick={() => {
                        setInstance(null);
                        setError(null);
                      }}
                    >
                      {t.back}
                    </button>
                    <button
                      type="button"
                      class="btn primary"
                      onClick={() => void startLogin()}
                      disabled={busy}
                    >
                      {busy ? <span class="spinner" /> : null}
                      {t.loginButton}
                    </button>
                  </div>
                </div>
              )}

              {store.accounts.length > 0 && (
                <div class="existing-accounts">
                  <div class="section-title" style={{ padding: "16px 0 8px" }}>
                    {t.accounts}
                  </div>
                  {store.accounts.map((account) => (
                    <button
                      key={account.id}
                      type="button"
                      class="list-row"
                      onClick={() => switchAccount(account.id)}
                    >
                      <img class="avatar" src={account.avatar} alt="" width={36} height={36} />
                      <div class="row-main">
                        <div class="row-title">{account.displayName}</div>
                        <div class="row-sub">{account.handle}</div>
                      </div>
                      <Icon name="arrow-right-line" size={16} />
                    </button>
                  ))}
                </div>
              )}
            </div>
            <img class="login-cat" src={loginCat} alt="" width={375} height={666} aria-hidden />
          </div>
        </div>
      </main>
      <footer class="login-footer" ref={supportRef}>
        <span>
          {t.landingDevelopedBy}{" "}
          <a href="https://github.com/lobovit" target="_blank" rel="noopener noreferrer">
            lobovit
          </a>
        </span>
        <button
          type="button"
          class="login-support-btn"
          aria-expanded={supportOpen}
          onClick={() => setSupportOpen((v) => !v)}
        >
          <Icon name="heart-line" size={14} />
          {t.supportProject}
        </button>
        {supportOpen && (
          <div class="login-support-pop" role="dialog" aria-label={t.supportProject}>
            <img src={supportQr} alt={t.supportQrAlt} width={180} height={180} />
            <p>{t.supportText}</p>
            <a
              href="https://nubank.com.br/cobrar/1z437/6accfdbf-ea20-443b-878e-5618946fad4a"
              target="_blank"
              rel="noopener noreferrer"
            >
              {t.supportLink}
            </a>
          </div>
        )}
      </footer>
    </div>
  );
}
